const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const message = data.message || {};

const phone = (data.key?.remoteJid || body.remoteJid || '').replace('@s.whatsapp.net', '').replace('@c.us', '');
const pushName = data.pushName || body.pushName || 'Cliente';
const messageId = data.key?.id || body.messageId || '';

const isAudio = !!(message.audioMessage || message.pttMessage);
const isImage = !!(message.imageMessage);
const isDocument = !!(message.documentMessage);
const isMedia = isImage || isDocument;

const mediaBase64 = (isImage || isDocument) ? (message.base64 || data.base64 || body.base64 || '') : '';
const mediaMimeType = message.imageMessage?.mimetype || message.documentMessage?.mimetype || 'image/jpeg';
const mediaCaption = message.imageMessage?.caption || message.documentMessage?.caption || '';
const mediaFileName = message.documentMessage?.fileName || '';

const audioBase64 = isAudio ? (message.base64 || data.base64 || body.base64 || message.audioMessage?.base64 || '') : '';
const audioUrl = message.audioMessage?.url || message.pttMessage?.url || '';

const text = message.conversation || message.extendedTextMessage?.text || body.text || '';

if (!phone || phone.includes('-')) {
  throw new Error('Mensagem ignorada: vazia ou de grupo');
}

return [{
  json: {
    phone,
    text,
    messageId,
    pushName,
    isAudio,
    isImage,
    isDocument,
    isMedia,
    audioUrl,
    audioBase64,
    mediaBase64,
    mediaMimeType,
    mediaCaption,
    mediaFileName
  }
}];

const geminiData = $input.first().json;
const dadosOriginais = $('Extrair Dados da Mensagem').item.json;
const textoTranscrito = geminiData?.candidates?.[0]?.content?.parts?.[0]?.text || geminiData?.text || '';
return [{
  json: {
    phone: dadosOriginais.phone,
    pushName: dadosOriginais.pushName,
    text: textoTranscrito,
    messageId: dadosOriginais.messageId,
    isAudio: true
  }
}];

const dados = $input.first().json;
const mediaBase64 = dados.mediaBase64 || '';
const mediaMimeType = dados.mediaMimeType || 'image/jpeg';
const mediaCaption = dados.mediaCaption || '';
const mediaFileName = dados.mediaFileName || '';
const isDocument = dados.isDocument;

const isPDF = isDocument && (mediaMimeType === 'application/pdf' || (mediaFileName || '').toLowerCase().endsWith('.pdf'));

let promptText;
if (isPDF) {
  promptText = mediaCaption ? `Cliente enviou arquivo com mensagem: "${mediaCaption}". Analise e descreva o que ve relacionado a vending machines ou o local.` : 'Analise este documento e descreva o que ve relacionado a vending machines ou infraestrutura.';
} else {
  promptText = mediaCaption ? `Cliente enviou imagem com mensagem: "${mediaCaption}". Descreva o que ve: espaco disponivel, tomadas, infraestrutura para maquina de venda automatica.` : 'Analise esta imagem e descreva o que ve: espaco disponivel, infraestrutura, condicoes para instalar uma vending machine.';
}

const geminiBody = {
  contents: [{
    parts: [
      { inlineData: { mimeType: mediaMimeType, data: mediaBase64 } },
      { text: `Voce e um consultor tecnico especialista em vending machines analisando imagens de ambientes. Descreva tecnicamente: espaco disponivel, condicoes de instalacao, necessidade de eletrica/agua, ponto de venda ideal, altura e largura disponivel. Seja especifico e objetivo. Responda em portugues.\n\n${promptText}` }
    ]
  }]
};

return [{ json: { ...dados, visionBodyStr: JSON.stringify(geminiBody) } }];

const visionData = $input.first().json;
const dadosOriginais = $('Extrair Dados da Mensagem').item.json;
const rawContent = visionData?.candidates?.[0]?.content?.parts?.[0]?.text || '';

const textoEnriquecido = `[CLIENTE ENVIOU ${dadosOriginais.isDocument ? 'ARQUIVO' : 'IMAGEM'}]\nAnalise tecnica: ${rawContent}${dadosOriginais.mediaCaption ? `\nMensagem junto a imagem: "${dadosOriginais.mediaCaption}"` : ''}`;

return [{
  json: {
    phone: dadosOriginais.phone,
    pushName: dadosOriginais.pushName,
    text: textoEnriquecido,
    messageId: dadosOriginais.messageId,
    isAudio: false,
    isImage: dadosOriginais.isImage,
    isDocument: dadosOriginais.isDocument,
    isMedia: true
  }
}];

let dadosFinal;
try {
  dadosFinal = $('Unificar Analise Vision').item.json;
  if (dadosFinal) return [{ json: dadosFinal }];
} catch(e) {}
try {
  dadosFinal = $('Unificar Transcricao').item.json;
  if (dadosFinal) return [{ json: dadosFinal }];
} catch(e) {}
dadosFinal = $('Extrair Dados da Mensagem').item.json;
return [{ json: dadosFinal }];

const extrair = $('Merge Texto+Audio').item.json;
let clienteData;
try {
  const novoResp = $('Cadastrar Novo Cliente').item.json;
  const arr = Array.isArray(novoResp) ? novoResp : [novoResp];
  if (arr.length > 0 && arr[0].id) clienteData = arr[0];
} catch(e) {}
if (!clienteData) {
  const existenteResp = $('Buscar Cliente').item.json;
  const arr = Array.isArray(existenteResp) ? existenteResp : [existenteResp];
  clienteData = arr.length > 0 ? arr[0] : {};
}
return [{
  json: {
    phone: extrair.phone,
    pushName: extrair.pushName,
    userMessage: extrair.text,
    isAudio: extrair.isAudio || false,
    isMedia: extrair.isMedia || false,
    clienteId: clienteData?.id,
    nomeCliente: clienteData?.nome || extrair.pushName,
    stage: clienteData?.stage || 'BOAS_VINDAS',
    empresa: clienteData?.empresa || '',
    tipoPessoa: clienteData?.tipo_pessoa || '',
    visitaAgendada: clienteData?.visita_agendada || false,
    dataVisita: clienteData?.data_visita || ''
  }
}];

