const dadosPrompt = $('Montar Prompt por Stage').item.json;
const geminiData = $input.first().json;

let respostaGPT = geminiData?.candidates?.[0]?.content?.parts?.[0]?.text
  || 'Ola! Sou o Lucas da OnVending. Como posso ajudar com sua vending machine?';

const respostaOriginal = respostaGPT;
let novoStage = dadosPrompt.novoStage;
const agendar = /\[AGENDAR:\s*([^\]]+)\]/i.test(respostaGPT);
const match = respostaGPT.match(/\[AGENDAR:\s*([^\]]+)\]/i);
const dataVisitaTexto = match ? match[1].trim() : '';

respostaGPT = respostaGPT
  .replace(/\[MOVER_PARA_ATENDIMENTO\]/gi, '')
  .replace(/\[MOVER_PARA_ORCAMENTO\]/gi, '')
  .replace(/\[MOVER_PARA_AGENDAMENTO\]/gi, '')
  .replace(/\[AGENDAR:[^\]]+\]/gi, '')
  .trim();

if (dadosPrompt.stage === 'BOAS_VINDAS' && respostaOriginal.includes('[MOVER_PARA_ATENDIMENTO]')) {
  novoStage = 'ATENDIMENTO';
} else if (dadosPrompt.stage === 'ATENDIMENTO' && respostaOriginal.includes('[MOVER_PARA_ORCAMENTO]')) {
  novoStage = 'ORCAMENTO';
} else if ((dadosPrompt.stage === 'ATENDIMENTO' || dadosPrompt.stage === 'ORCAMENTO') && respostaOriginal.includes('[MOVER_PARA_AGENDAMENTO]')) {
  novoStage = 'AGENDAMENTO';
}

if (agendar && novoStage !== 'AGENDAMENTO') {
  novoStage = 'AGENDAMENTO';
}

return [{
  json: {
    phone: dadosPrompt.phone,
    clienteId: dadosPrompt.clienteId,
    userMessage: dadosPrompt.userMessage,
    respostaGPT,
    stage: dadosPrompt.stage,
    novoStage,
    agendar,
    dataVisitaTexto
  }
}];

const resp = $('Extrair Resposta Gemini').item.json;
const payload = [
  { cliente_id: resp.clienteId, role: 'user',      conteudo: resp.userMessage  || '' },
  { cliente_id: resp.clienteId, role: 'assistant', conteudo: resp.respostaGPT || '' }
];
return [{
  json: {
    bodyStr: JSON.stringify(payload),
    phone:           resp.phone,
    clienteId:       resp.clienteId,
    userMessage:     resp.userMessage,
    respostaGPT:     resp.respostaGPT,
    stage:           resp.stage,
    novoStage:       resp.novoStage,
    agendar:         resp.agendar,
    dataVisitaTexto: resp.dataVisitaTexto
  }
}];
